50: /**
51:  * Set the system properties, org.jansi.lib.path, org.jansi.lib.name,
52:  * appropriately so that jansi can find *.dll, *.jnilib and
53:  * *.so files, according to the current OS (win, linux, mac).
54:  * <p>
55:  * The library files are automatically extracted from this project's package
56:  * (JAR).
57:  * <p>
58:  * usage: call {@link #initialize()} before using Jansi.
59:  */
60: public class JansiLoader {
61: 
62:     private static boolean loaded = false;
63:     private static String nativeLibraryPath;
64:     private static String nativeLibrarySourceUrl;
65: 
66:     /**
67:      * Loads Jansi native library.
68:      *
69:      * @return True if jansi native library is successfully loaded; false
70:      * otherwise.
71:      */
72:     public static synchronized boolean initialize() {
73:         // only cleanup before the first extract
74:         if (!loaded) {
75:             Thread cleanup = new Thread(JansiLoader::cleanup, "cleanup");
76:             cleanup.setPriority(Thread.MIN_PRIORITY);
77:             cleanup.setDaemon(true);
78:             cleanup.start();
79:         }
80:         try {
81:             loadJansiNativeLibrary();
82:         } catch (Exception e) {
83:             if (!Boolean.parseBoolean(System.getProperty(AnsiConsole.JANSI_GRACEFUL, "true"))) {
84:                 throw new RuntimeException(
85:                         "Unable to load jansi native library. You may want set the `jansi.graceful` system property to true to be able to use Jansi on your platform",
86:                         e);
87:             }
88:         }
89:         return loaded;
90:     }
91: 
92:     public static String getNativeLibraryPath() {
93:         return nativeLibraryPath;
94:     }
95: 
96:     public static String getNativeLibrarySourceUrl() {
97:         return nativeLibrarySourceUrl;
98:     }
99: 
100:     private static File getTempDir() {
101:         return new File(System.getProperty("jansi.tmpdir", System.getProperty("java.io.tmpdir")));
102:     }
103: 
104:     /**
105:      * Deleted old native libraries e.g. on Windows the DLL file is not removed
106:      * on VM-Exit (bug #80)
107:      */
108:     static void cleanup() {
109:         String tempFolder = getTempDir().getAbsolutePath();
110:         File dir = new File(tempFolder);
111: 
112:         File[] nativeLibFiles = dir.listFiles(new FilenameFilter() {
113:             private final String searchPattern = "jansi-" + getVersion();
114: 
115:             public boolean accept(File dir, String name) {
116:                 return name.startsWith(searchPattern) && !name.endsWith(".lck");
117:             }
118:         });
119:         if (nativeLibFiles != null) {
120:             for (File nativeLibFile : nativeLibFiles) {
121:                 File lckFile = new File(nativeLibFile.getAbsolutePath() + ".lck");
122:                 if (!lckFile.exists()) {
123:                     try {
124:                         nativeLibFile.delete();
125:                     } catch (SecurityException e) {
126:                         System.err.println("Failed to delete old native lib" + e.getMessage());
127:                     }
128:                 }
129:             }
130:         }
131:     }
