133:     private static int readNBytes(InputStream in, byte[] b) throws IOException {
134:         int n = 0;
135:         int len = b.length;
136:         while (n < len) {
137:             int count = in.read(b, n, len - n);
138:             if (count <= 0) break;
139:             n += count;
140:         }
141:         return n;
142:     }
143: 
144:     private static String contentsEquals(InputStream in1, InputStream in2) throws IOException {
145:         byte[] buffer1 = new byte[8192];
146:         byte[] buffer2 = new byte[8192];
147:         int numRead1;
148:         int numRead2;
149:         while (true) {
150:             numRead1 = readNBytes(in1, buffer1);
151:             numRead2 = readNBytes(in2, buffer2);
152:             if (numRead1 > 0) {
153:                 if (numRead2 <= 0) {
154:                     return "EOF on second stream but not first";
155:                 }
156:                 if (numRead2 != numRead1) {
157:                     return "Read size different (" + numRead1 + " vs " + numRead2 + ")";
158:                 }
159:                 // Otherwise same number of bytes read
160:                 for (int i = 0; i < numRead1; i++) {
161:                     if (buffer1[i] != buffer2[i]) {
162:                         return "Content differs";
163:                     }
164:                 }
165:                 // Otherwise same bytes read, so continue ...
166:             } else {
167:                 // Nothing more in stream 1 ...
168:                 if (numRead2 > 0) {
169:                     return "EOF on first stream but not second";
170:                 } else {
171:                     return null;
172:                 }
173:             }
174:         }
175:     }
