177:     /**
178:      * Extracts and loads the specified library file to the target folder
179:      *
180:      * @param libFolderForCurrentOS Library path.
181:      * @param libraryFileName       Library name.
182:      * @param targetFolder          Target folder.
183:      * @return
184:      */
185:     private static boolean extractAndLoadLibraryFile(
186:             String libFolderForCurrentOS, String libraryFileName, String targetFolder) {
187:         String nativeLibraryFilePath = libFolderForCurrentOS + "/" + libraryFileName;
188:         // Include architecture name in temporary filename in order to avoid conflicts
189:         // when multiple JVMs with different architectures running at the same time
190:         String uuid = randomUUID();
191:         String extractedLibFileName = String.format("jansi-%s-%s-%s", getVersion(), uuid, libraryFileName);
192:         String extractedLckFileName = extractedLibFileName + ".lck";
193: 
194:         File extractedLibFile = new File(targetFolder, extractedLibFileName);
195:         File extractedLckFile = new File(targetFolder, extractedLckFileName);
196: 
197:         try {
198:             // Extract a native library file into the target directory
199:             try (InputStream in = JansiLoader.class.getResourceAsStream(nativeLibraryFilePath)) {
200:                 if (!extractedLckFile.exists()) {
201:                     new FileOutputStream(extractedLckFile).close();
202:                 }
203:                 Files.copy(in, extractedLibFile.toPath(), StandardCopyOption.REPLACE_EXISTING);
204:             } finally {
205:                 // Delete the extracted lib file on JVM exit.
206:                 extractedLibFile.deleteOnExit();
207:                 extractedLckFile.deleteOnExit();
208:             }
209: 
210:             // Set executable (x) flag to enable Java to load the native library
211:             extractedLibFile.setReadable(true);
212:             extractedLibFile.setWritable(true);
213:             extractedLibFile.setExecutable(true);
214: 
215:             // Check whether the contents are properly copied from the resource folder
216:             try (InputStream nativeIn = JansiLoader.class.getResourceAsStream(nativeLibraryFilePath)) {
217:                 try (InputStream extractedLibIn = new FileInputStream(extractedLibFile)) {
218:                     String eq = contentsEquals(nativeIn, extractedLibIn);
219:                     if (eq != null) {
220:                         throw new RuntimeException(String.format(
221:                                 "Failed to write a native library file at %s because %s", extractedLibFile, eq));
222:                     }
223:                 }
224:             }
225: 
226:             // Load library
227:             if (loadNativeLibrary(extractedLibFile)) {
228:                 nativeLibrarySourceUrl =
229:                         JansiLoader.class.getResource(nativeLibraryFilePath).toExternalForm();
230:                 return true;
231:             }
232:         } catch (IOException e) {
233:             System.err.println(e.getMessage());
234:         }
235:         return false;
236:     }
