242:     /**
243:      * Loads native library using the given path and name of the library.
244:      *
245:      * @param libPath Path of the native library.
246:      * @return True for successfully loading; false otherwise.
247:      */
248:     private static boolean loadNativeLibrary(File libPath) {
249:         if (libPath.exists()) {
250:             try {
251:                 String path = libPath.getAbsolutePath();
252:                 System.load(path);
253:                 nativeLibraryPath = path;
254:                 return true;
255:             } catch (UnsatisfiedLinkError e) {
256:                 if (!libPath.canExecute()) {
257:                     // NOTE: this can be tested using something like:
258:                     // docker run --rm --tmpfs /tmp -v $PWD:/jansi openjdk:11 java -jar
259:                     // /jansi/target/jansi-xxx-SNAPSHOT.jar
260:                     System.err.printf(
261:                             "Failed to load native library:%s. The native library file at %s is not executable, "
262:                                     + "make sure that the directory is mounted on a partition without the noexec flag, or set the "
263:                                     + "jansi.tmpdir system property to point to a proper location.  osinfo: %s%n",
264:                             libPath.getName(), libPath, OSInfo.getNativeLibFolderPathForCurrentOS());
265:                 } else {
266:                     System.err.printf(
267:                             "Failed to load native library:%s. osinfo: %s%n",
268:                             libPath.getName(), OSInfo.getNativeLibFolderPathForCurrentOS());
269:                 }
270:                 System.err.println(e);
271:                 return false;
272:             }
273: 
274:         } else {
275:             return false;
276:         }
277:     }
