279:     /**
280:      * Loads jansi library using given path and name of the library.
281:      *
282:      * @throws
283:      */
284:     private static void loadJansiNativeLibrary() throws Exception {
285:         if (loaded) {
286:             return;
287:         }
288: 
289:         List<String> triedPaths = new LinkedList<String>();
290: 
291:         // Try loading library from library.jansi.path library path */
292:         String jansiNativeLibraryPath = System.getProperty("library.jansi.path");
293:         String jansiNativeLibraryName = System.getProperty("library.jansi.name");
294:         if (jansiNativeLibraryName == null) {
295:             jansiNativeLibraryName = System.mapLibraryName("jansi");
296:             assert jansiNativeLibraryName != null;
297:             if (jansiNativeLibraryName.endsWith(".dylib")) {
298:                 jansiNativeLibraryName = jansiNativeLibraryName.replace(".dylib", ".jnilib");
299:             }
300:         }
301: 
302:         if (jansiNativeLibraryPath != null) {
303:             String withOs = jansiNativeLibraryPath + "/" + OSInfo.getNativeLibFolderPathForCurrentOS();
304:             if (loadNativeLibrary(new File(withOs, jansiNativeLibraryName))) {
305:                 loaded = true;
306:                 return;
307:             } else {
308:                 triedPaths.add(withOs);
309:             }
310: 
311:             if (loadNativeLibrary(new File(jansiNativeLibraryPath, jansiNativeLibraryName))) {
312:                 loaded = true;
313:                 return;
314:             } else {
315:                 triedPaths.add(jansiNativeLibraryPath);
316:             }
317:         }
318: 
319:         // Load the os-dependent library from the jar file
320:         String packagePath = JansiLoader.class.getPackage().getName().replace('.', '/');
321:         jansiNativeLibraryPath =
322:                 String.format("/%s/native/%s", packagePath, OSInfo.getNativeLibFolderPathForCurrentOS());
323:         boolean hasNativeLib = hasResource(jansiNativeLibraryPath + "/" + jansiNativeLibraryName);
324: 
325:         if (hasNativeLib) {
326:             // temporary library folder
327:             String tempFolder = getTempDir().getAbsolutePath();
328:             // Try extracting the library from jar
329:             if (extractAndLoadLibraryFile(jansiNativeLibraryPath, jansiNativeLibraryName, tempFolder)) {
330:                 loaded = true;
331:                 return;
332:             } else {
333:                 triedPaths.add(jansiNativeLibraryPath);
334:             }
335:         }
336: 
337:         // As a last resort try from java.library.path
338:         String javaLibraryPath = System.getProperty("java.library.path", "");
339:         for (String ldPath : javaLibraryPath.split(File.pathSeparator)) {
340:             if (ldPath.isEmpty()) {
341:                 continue;
342:             }
343:             if (loadNativeLibrary(new File(ldPath, jansiNativeLibraryName))) {
344:                 loaded = true;
345:                 return;
346:             } else {
347:                 triedPaths.add(ldPath);
348:             }
349:         }
350: 
351:         throw new Exception(String.format(
352:                 "No native library found for os.name=%s, os.arch=%s, paths=[%s]",
353:                 OSInfo.getOSName(), OSInfo.getArchName(), String.join(File.pathSeparator, triedPaths)));
354:     }
